  for (const q of squadrons) {
    if (q._px != null) { const v = Math.hypot(q.x - q._px, (q.y || 0) - q._py, q.z - q._pz) / dt; q.vel = (q.vel || 0) + (Math.min(v, 200) - (q.vel || 0)) * 0.1; }
    q._px = q.x; q._py = q.y || 0; q._pz = q.z;
  }
