function togglePause() { if (GAME.phase === 'simedit') return; if (NET.on) { toast('多人戰鬥不能暫停', 'hint'); return; } /* 模擬室編輯中保持暫停 */ paused = !paused; if (typeof TAC !== 'undefined' && TAC.open) TAC.autoPaused = false; updateTimeUI(); }
