  if (fogE === 1) gEl('bh-t1').textContent = `${nm(1)} ？？？（雷達受干擾）`; else { gEl('bh-t1').textContent = `${nm(1)} ${Math.round(e * 100)}%　${ships5(a1)} 艘`; gEl('bh-b1').style.width = e * 100 + '%'; }
