    terrain: [stT('nebula', 0, -60, 280, 20), stT('rock', 380, 140, 60)],
    foes: [['聯盟伏擊艦隊', '葛瑞絲・卡特萊', 'dmg', 3, ['focus', 'rapid'], 'heavy', 0.55, 'crescent', 'kite']],
    ev: [['佩蕾的機動艦隊', ['佩蕾', 'speed', 3, ['charge']], 0.32, 'raider', 'wedge', 'right', [45, 80]]],
