  ctx.shadowBlur = 0;
  const gr = ctx.createLinearGradient(0, -size / 2, 0, size / 2); gr.addColorStop(0, '#ffffff'); gr.addColorStop(0.55, col.main); gr.addColorStop(1, col.glow);   // 漸層填色
