    const ty = t.y != null && Math.abs(t.y) >= 5 ? `　${t.y > 0 ? '▲' : '▼'}${Math.round(Math.abs(t.y))}` : '';
    c.fillStyle = col; c.font = `${uiPx(12.5)}px system-ui`; c.textAlign = 'center'; c.fillText(TERRAIN_TYPES[t.type].name + ty, tx(t.x), tz(t.z - t.r) - 4);
