    card.querySelector('.tac-info').textContent = `${ships5(n)} 艘（${Math.round(n / f.initial * 100)}%）・${g ? FORMATIONS[g.formation].name : '-'}・${comp.map((v, k) => (v ? SHIP_TYPES[k].name + ships5(v) : '')).filter(Boolean).join(' ')}${ammo}`;
