  const list = bridgeFleets(); if (!list.length) return false;
  if (!f) { const sf = [...selected].map((q) => q.fleet).filter(Boolean); f = sf.length && sf.every((x) => x === sf[0]) && list.includes(sf[0]) ? sf[0] : list[0]; }
