  if (keyHeld('cam_right') || keyHeld('cam_yaw_r')) { BR.kYaw += ys; k = true; }
  if (keyHeld('cam_up') || keyHeld('cam_pitch_up')) { BR.tPitch = bridgeClampPitch(BR.tPitch + ps); k = true; }
